    "Items": "Vitu",
    "privacy_sec1_title": "1. Utangulizi na Ahadi ya Faragha ya Upishi",
    "privacy_sec1_body": "Karibu katika Mkahawa wa Kolay (\"Kolay\", \"sisi\", \"yetu\"). Tunaheshimu faragha yako na tumejitolea kulinda data ya kibinafsi ya wageni wetu, watembeleaji wa tovuti, waombaji kazi, na watumiaji wa jukwaa.",
    "privacy_sec2_title": "2. Taarifa Tunazokusanya",
    "privacy_sec2_body": "Tunakusanya taarifa za kibinafsi zinazotolewa kwa hiari wakati wa kuagiza na mwingiliano:",
    "privacy_bullet1": "Mawasiliano ya Mgeni: Jina kamili, nambari ya simu, barua pepe, na anwani ya utoaji.",
    "privacy_bullet2": "Mapendeleo ya Chakula na Agizo: Vitu vya kikapu, maelezo ya lishe, maelekezo ya utoaji au kubeba.",
    "privacy_bullet3": "Maelezo ya Hifadhi ya Meza: Idadi ya wageni, muda uliotombwa, na mapendeleo ya viti.",
    "privacy_bullet4": "Maombi ya Kazi: Wasifu, historia ya kazi, na maombi ya kurejesha mkataba.",
    "privacy_bullet5": "Hifadhi ya Mapendeleo: Lugha iliyochaguliwa na hali ya kikapu imehifadhiwa kwenye kivinjari.",
    "privacy_sec3_title": "3. Dhumuni na Matumizi ya Data",
    "privacy_sec3_body": "Taarifa yako inatumika pekee kutoa uzoefu wa kipekee wa chakula:",
    "privacy_use1": "Kuandaa, kutuma, na kukamilisha maagizo yako ya chakula na vinywaji kwa usahihi.",
    "privacy_use2": "Kuhakikisha miadi ya meza na kuarifu wafanyakazi kuhusu maombi maalum ya kuwasili.",
    "privacy_use3": "Kutuma taarifa za hali ya agizo, risiti za kidijitali, na uthibitisho wa miadi.",
    "privacy_use4": "Kutathmini maombi ya kazi na kushughulikia urejesho wa mikataba ya wafanyakazi.",
    "privacy_sec4_title": "4. Hifadhi ya Mahali ya Kivinjari na Vidakuzi",
    "privacy_sec4_body": "Mkahawa wa Kolay unatumia Hifadhi ya Mahali ya Kivinjari ili kuhakikisha majibu ya haraka.",
    "privacy_sec5_title": "5. Ulinzi wa Data na Kutotoa kwa Watu wa Nje",
    "privacy_sec5_body": "Tunatumia usimbaji wa kiwango cha juu. HATUSALIMISHI au kuuza data ya kibinafsi ya wageni kwa watangazaji wa nje.",
    "privacy_effective": "Inaanza Septemba 2026",
    "modal_open_full": "Fungua Ukurasa Kamili",
    "modal_close": "Funga Ukurasa",
    "terms_sec1_title": "1. Kukubali Masharti",
    "terms_sec1_body": "Kwa kufikia au kutumia jukwaa la kidijitali la Mkahawa wa Kolay, unakubali kuwajibika na Masharti haya ya Matumizi.",
    "terms_sec2_title": "2. Maagizo ya Mtandaoni, Bei na Punguzo la Wanachama",
    "terms_sec2_body": "Maagizo yote yanategemea upatikanaji wa chakula na uthibitisho wa mpishi. Bei zote ni KES na zinajumuisha 16% VAT.",
    "terms_bullet1": "Bei zote za menyu zinaonyeshwa kwa Shilingi za Kenya (KES) na zinajumuisha 16% VAT.",
    "terms_bullet2": "Wanachama waliosajiliwa wa Kolay wanapata punguzo la 10% kwa vyakula maalum vya msimu.",
    "terms_bullet3": "Njia za malipo zinajumuisha pesa taslimu unapoletewa na M-Pesa au kadi ya benki.",
    "terms_bullet4": "Mabadiliko ya agizo hayawezi kuhakikishwa mara tu agizo linapoingia katika hali ya \"Inaandaliwa\" jikoni.",
    "terms_sec3_title": "3. Hifadhi ya Meza na Muda wa Kuchelewa wa Dakika 15",
    "terms_sec3_body": "Miadi ya meza iliyowekwa inahifadhiwa kwa muda usizidi dakika 15 baada ya muda uliopangwa.",
    "terms_sec4_title": "4. Ufikiaji wa Bandari na Usiri wa Akaunti",
    "terms_sec4_body": "Watumiaji wanawajibika kulinda taarifa zao za kuingia. Bandari ya wafanyakazi ni kwa walioidhinishwa pekee.",
    "terms_sec5_title": "5. Maombi ya Kazi na Urejesho wa Mikataba",
    "terms_sec5_body": "Waombaji wanaotuma maombi ya kazi au kurejesha mikataba wanathibitisha kuwa taarifa zote zilizotolewa ni za kweli.",
    "terms_sec6_title": "6. Hakimiliki na Sheria Inayotawala",
    "terms_sec6_body": "Chapa zote, nembo, menyu za chakula, picha, na mfumo wa programu ni mali halali ya Mkahawa wa Kolay.",
