    "Items": "件",
    "privacy_sec1_title": "1. 引言与烹饪隐私承诺",
    "privacy_sec1_body": "欢迎光临 Kolay 餐厅（以下简称“Kolay”、“我们”）。我们尊重您的隐私，并致力于保护客人的个人数据。",
    "privacy_sec2_title": "2. 我们收集的信息",
    "privacy_sec2_body": "我们收集在客人互动和下单期间自愿提供的个人信息：",
    "privacy_bullet1": "客人联系方式：全名、电话号码、电子邮件和送货地址。",
    "privacy_bullet2": "订单及用餐偏好：购物车商品、饮食要求、配送/自提指示。",
    "privacy_bullet3": "餐桌预订详情：人数、预订时间、特殊场合及座位偏好。",
    "privacy_bullet4": "职业与求职申请：履历、工作经历、资质及员工续约申请。",
    "privacy_bullet5": "偏好存储：选择的显示语言和活跃购物车状态保存在本地。",
    "privacy_sec3_title": "3. 数据收集目的与用途",
    "privacy_sec3_body": "您的信息严格用于提供卓越的餐馆用餐体验：",
    "privacy_use1": "准确准备、发送和完成您的餐饮订单。",
    "privacy_use2": "确认餐桌预订并告知接待人员特殊到达要求。",
    "privacy_use3": "发送订单状态更新、电子收据和预订确认。",
    "privacy_use4": "评估职业申请及处理员工续约。",
    "privacy_sec4_title": "4. 浏览器本地存储与 Cookie",
    "privacy_sec4_body": "Kolay 餐厅利用浏览器本地存储和极简会话令牌来确保即时响应。",
    "privacy_sec5_title": "5. 数据安全保障与第三方保密承诺",
    "privacy_sec5_body": "我们采用企业级加密和管理安全措施。我们绝不向第三方广告商出售、出租或交易客人的个人数据。",
    "privacy_effective": "生效日期：2026年9月",
    "modal_open_full": "打开完整页面",
    "modal_close": "关闭窗口",
    "terms_sec1_title": "1. 条款的接受",
    "terms_sec1_body": "访问或使用 Kolay 餐厅的数字平台、POS 工具或点餐预订系统，即表示您同意接受本使用条款的约束。",
    "terms_sec2_title": "2. 在线订单、价格及会员折扣",
    "terms_sec2_body": "所有订单受菜品供应情况和厨师确认限制。所有菜单价格均包含 16% 增值税。",
    "terms_bullet1": "所有菜单价格均以肯尼亚先令 (KES) 显示，并已包含 16% 的增值税。",
    "terms_bullet2": "注册 Kolay 会员尊享时令特色菜品 9 折优惠。",
    "terms_bullet3": "支付方式包括货到付款/自提现金，以及支持的 M-Pesa 或银行卡支付。",
    "terms_bullet4": "一旦订单在厨房显示系统 (KDS) 中进入“准备中”状态，将无法保证修改订单。",
    "terms_sec3_title": "3. 餐桌预订与 15 分钟宽限期",
    "terms_sec3_body": "通过本平台预订的餐桌最多保留至预订到达时间后的 15 分钟。",
    "terms_sec4_title": "4. 门户访问与账户保密",
    "terms_sec4_body": "用户负责保管其登录凭据。员工门户、KDS、POS 和管理控制台仅限于授权人员使用。",
    "terms_sec5_title": "5. 职位申请与员工合同续约",
    "terms_sec5_body": "提交求职申请或员工续约表格的应聘者须保证所提供的所有履历和声明均真实有效。",
    "terms_sec6_title": "6. 知识产权与管辖法律",
    "terms_sec6_body": "所有品牌标识、烹饪菜单、摄影作品、UI 设计及软件代码均属于 Kolay 餐厅的专有知识产权。",
