    "Items": "आइटम",
    "privacy_sec1_title": "1. परिचय एवं पाक गोपनीयता प्रतिबद्धता",
    "privacy_sec1_body": "Kolay रेस्तरां में आपका स्वागत है। हम आपकी गोपनीयता का सम्मान करते हैं और आपके डेटा की सुरक्षा के लिए प्रतिबद्ध हैं।",
    "privacy_sec2_title": "2. जानकारी जो हम एकत्र करते हैं",
    "privacy_sec2_body": "हम मेहमानों की बातचीत और ऑर्डर देने के दौरान स्वेच्छा से दी गई व्यक्तिगत जानकारी एकत्र करते हैं:",
    "privacy_bullet1": "संपर्क विवरण: पूरा नाम, फोन नंबर, ईमेल और डिलीवरी पता।",
    "privacy_bullet2": "ऑर्डर प्राथमिकताएं: कार्ट आइटम, आहार संबंधी नोट्स, डिलीवरी निर्देश।",
    "privacy_bullet3": "आरक्षण विवरण: अतिथियों की संख्या, समय और बैठने की प्राथमिकताएं।",
    "privacy_bullet4": "करियर आवेदन: रिज्यूमे, कार्य अनुभव, क्रेडेंशियल्स और अनुबंध नवीनीकरण।",
    "privacy_bullet5": "प्राथमिकता भंडारण: चुनी गई भाषा और सक्रिय कार्ट स्थिति स्थानीय रूप से सहेजी गई है।",
    "privacy_sec3_title": "3. उद्देश्य और डेटा का उपयोग",
    "privacy_sec3_body": "आपकी जानकारी का उपयोग केवल उत्कृष्ट भोजन अनुभव प्रदान करने के लिए किया जाता है:",
    "privacy_use1": "आपके भोजन और पेय के आदेशों को सटीक रूप से तैयार करना और पूरा करना।",
    "privacy_use2": "टेबल बुकिंग सुरक्षित करना और कर्मचारियों को विशेष अनुरोधों से अवगत कराना।",
    "privacy_use3": "ऑर्डर स्थिति अपडेट, डिजिटल रसीदें और आरक्षण की पुष्टि भेजना।",
    "privacy_use4": "करियर आवेदनों का मूल्यांकन करना और कर्मचारियों के अनुबंध नवीनीकरण को संसाधित करना।",
    "privacy_sec4_title": "4. ब्राउज़र लोकल स्टोरेज और कुकीज़",
    "privacy_sec4_body": "Kolay रेस्तरां त्वरित प्रतिक्रिया सुनिश्चित करने के लिए ब्राउज़र लोकल स्टोरेज का उपयोग करता है।",
    "privacy_sec5_title": "5. डेटा सुरक्षा और तृतीय-पक्ष गैर-प्रकटीकरण",
    "privacy_sec5_body": "हम एंटरप्राइज-ग्रेड एन्क्रिप्शन का उपयोग करते हैं। हम कभी भी किसी तीसरे पक्ष को डेटा नहीं बेचते हैं।",
    "privacy_effective": "प्रभावी: सितंबर 2026",
    "modal_open_full": "पूरा पृष्ठ खोलें",
    "modal_close": "बंद करें",
    "terms_sec1_title": "1. शर्तों की स्वीकृति",
    "terms_sec1_body": "Kolay रेस्तरां के डिजिटल प्लेटफॉर्म का उपयोग करके, आप इन उपयोग की शर्तों से बंधे होने के लिए सहमत हैं।",
    "terms_sec2_title": "2. ऑनलाइन ऑर्डर, मूल्य निर्धारण और सदस्य छूट",
    "terms_sec2_body": "सभी ऑर्डर उपलब्धता के अधीन हैं। सभी कीमतों में 16% वैट शामिल है।",
    "terms_bullet1": "सभी मूल्य केन्याई शिलिंग (KES) में दिखाए गए हैं और 16% वैट शामिल हैं।",
    "terms_bullet2": "पंजीकृत Kolay सदस्यों को मौसमी व्यंजनों पर 10% की छूट मिलती है।",
    "terms_bullet3": "भुगतान के तरीकों में डिलीवरी पर नकद और M-Pesa या कार्ड शामिल हैं।",
    "terms_bullet4": "किचन डिस्प्ले पर \"तैयार हो रहा है\" स्थिति में जाने के बाद ऑर्डर में बदलाव की गारंटी नहीं दी जा सकती।",
    "terms_sec3_title": "3. टेबल आरक्षण और 15 मिनट की छूट अवधि",
    "terms_sec3_body": "हमारे प्लेटफॉर्म के माध्यम से बुक की गई टेबल आरक्षण समय से अधिकतम 15 मिनट तक रखी जाती हैं।",
    "terms_sec4_title": "4. पोर्टल पहुंच और खाता गोपनीयता",
    "terms_sec4_body": "उपयोगकर्ता अपने लॉगिन क्रेडेंशियल्स की सुरक्षा के लिए जिम्मेदार हैं। स्टाफ पोर्टल केवल अधिकृत कर्मियों तक सीमित है।",
    "terms_sec5_title": "5. करियर आवेदन और अनुबंध नवीनीकरण",
    "terms_sec5_body": "नौकरी के आवेदन प्रस्तुत करने वाले आवेदक यह प्रमाणित करते हैं कि सभी जानकारी सटीक है।",
    "terms_sec6_title": "6. बौद्धिक संपदा और लागू कानून",
    "terms_sec6_body": "सभी ब्रांडिंग, लोगो, मेनू, तस्वीरें और सॉफ्टवेयर Kolay रेस्तरां की संपत्ति हैं।",
