    "privacy_sec1_title": "1. Introducción y Compromiso de Privacidad Culinaria",
    "privacy_sec1_body": "Bienvenido a Kolay Restaurant. Respetamos su privacidad y nos comprometemos a proteger los datos personales de nuestros clientes.",
    "privacy_sec2_title": "2. Información que Recopilamos",
    "privacy_sec2_body": "Recopilamos información personal proporcionada voluntariamente durante los pedidos y la interacción:",
    "privacy_bullet1": "Detalles de contacto: Nombre completo, teléfono, correo electrónico y dirección.",
    "privacy_bullet2": "Preferencias de pedido: Artículos del carrito, notas dietéticas e instrucciones de entrega.",
    "privacy_bullet3": "Detalles de reserva: Número de personas, hora solicitada y preferencias de mesa.",
    "privacy_bullet4": "Solicitudes de empleo: Currículum, historial laboral y renovación de contratos.",
    "privacy_bullet5": "Almacenamiento de preferencias: Idioma seleccionado y estado del carrito guardados localmente.",
    "privacy_sec3_title": "3. Propósito y Uso de los Datos",
    "privacy_sec3_body": "Su información se utiliza estrictamente para brindar una experiencia gastronómica excepcional:",
    "privacy_use1": "Preparar, despachar y cumplir con sus pedidos de comida y bebida con precisión.",
    "privacy_use2": "Asegurar reservas de mesa y notificar al personal sobre solicitudes especiales.",
    "privacy_use3": "Enviar actualizaciones de estado del pedido, recibos digitales y confirmaciones.",
    "privacy_use4": "Evaluar solicitudes de empleo y procesar renovaciones de contratos de empleados.",
    "privacy_sec4_title": "4. Almacenamiento Local del Navegador y Cookies",
    "privacy_sec4_body": "Kolay Restaurant utiliza el Almacenamiento Local del navegador para garantizar una respuesta instantánea.",
    "privacy_sec5_title": "5. Salvaguardias de Datos y No Divulgación a Terceros",
    "privacy_sec5_body": "Empleamos cifrado de nivel empresarial. NUNCA vendemos ni alquilamos datos personales a terceros.",
    "privacy_effective": "Efectivo a partir de Septiembre de 2026",
    "modal_open_full": "Abrir Página Completa",
    "modal_close": "Cerrar Extensión",
    "terms_sec1_title": "1. Aceptación de los Términos",
    "terms_sec1_body": "Al acceder o utilizar la plataforma digital de Kolay Restaurant, acepta quedar vinculado por estos Términos de Uso.",
    "terms_sec2_title": "2. Pedidos en Línea, Precios y Descuentos de Miembros",
    "terms_sec2_body": "Todos los pedidos están sujetos a disponibilidad y confirmación. Los precios incluyen el 16% de IVA.",
    "terms_bullet1": "Todos los precios se muestran en Chelines Kenianos (KES) e incluyen el 16% de IVA.",
    "terms_bullet2": "Los miembros registrados disfrutaron de un 10% de descuento en especialidades de temporada.",
    "terms_bullet3": "Los métodos de pago incluyen efectivo contra entrega y pagos con M-Pesa o tarjeta.",
    "terms_bullet4": "No se garantizan cambios en el pedido una vez pase al estado \"En preparación\".",
    "terms_sec3_title": "3. Reservas de Mesa y Período de Gracia de 15 Minutos",
    "terms_sec3_body": "Las reservas de mesa se mantienen durante un período de gracia máximo de 15 minutos.",
    "terms_sec4_title": "4. Acceso al Portal y Confidencialidad de la Cuenta",
    "terms_sec4_body": "Los usuarios son responsables de proteger sus credenciales. Los portales del personal son estrictamente restringidos.",
    "terms_sec5_title": "5. Solicitudes de Empleo y Renovación de Contratos",
    "terms_sec5_body": "Los solicitantes certifican que todas las credenciales y representaciones presentadas son precisas.",
    "terms_sec6_title": "6. Propiedad Intelectual y Ley Aplicable",
    "terms_sec6_body": "Toda la marca, logotipos, menús y software son propiedad intelectual exclusiva de Kolay Restaurant.",
