    "privacy_sec1_title": "1. المقدمة والالتزام بالخصوصية الطهوية",
    "privacy_sec1_body": "مرحباً بكم في مطعم كولاي. نحن نحترم خصوصيتكم ونلتزم بحماية البيانات الشخصية لضيوفنا.",
    "privacy_sec2_title": "2. المعلومات التي نجمعها",
    "privacy_sec2_body": "نجمع المعلومات الشخصية المقدمة طوعاً أثناء الطلب والتفاعل:",
    "privacy_bullet1": "تفاصيل الاتصال: الاسم الكامل، رقم الهاتف، البريد الإلكتروني، وعنوان التوصيل.",
    "privacy_bullet2": "تفضيلات الطلب: عناصر السلة، الملاحظات الغذائية، وتعليمات التوصيل.",
    "privacy_bullet3": "تفاصيل الحجز: عدد الضيوف، الوقت المطلوب، وتفضيلات الجلوس.",
    "privacy_bullet4": "طلبات الوظائف: السيرة الذاتية، خبرات العمل، وطلبات تجديد العقود.",
    "privacy_bullet5": "تخزين التفضيلات: اللغة المختارة وحالة السلة المحفوظة محلياً.",
    "privacy_sec3_title": "3. الغرض واستخدام البيانات",
    "privacy_sec3_body": "تستخدم معلوماتكم حصرياً لتقديم تجربة طعام استثنائية:",
    "privacy_use1": "تحضير وإرسال وتنفيذ طلبات الطعام والمشروبات بدقة.",
    "privacy_use2": "تأكيد حجوزات الطاولات وإشعارات الطلبات الخاصة للضيوف.",
    "privacy_use3": "إرسال تحديثات حالة الطلب والإيصالات الرقمية وتأكيدات الحجز.",
    "privacy_use4": "تقييم طلبات التوظيف ومعالجة تجديد عقود الموظفين.",
    "privacy_sec4_title": "4. التخزين المحلي للمتصفح وملفات تعريف الارتباط",
    "privacy_sec4_body": "يستخدم مطعم كولاي التخزين المحلي للمتصفح لضمان الاستجابة الفورية.",
    "privacy_sec5_title": "5. ضمانات البيانات وعدم الإفصاح للطرف الثالث",
    "privacy_sec5_body": "نستخدم التشفير على مستوى المؤسسات. نحن لا نبيع ولا نؤجر البيانات الشخصية لأي طرف ثالث.",
    "privacy_effective": "ساري اعتباراً من سبتمبر 2026",
