    "terms_sec1_title": "1. القبول بالشروط",
    "terms_sec1_body": "باستخدام منصة مطعم كولاي الرقمية، فإنك توافق على الالتزام بشروط الاستخدام هذه.",
    "terms_sec2_title": "2. الطلبات عبر الإنترنت، الأسعار وخصومات الأعضاء",
    "terms_sec2_body": "جميع الطلبات تخضع لتوافر الأصناف وتأكيد الشيف. جميع الأسعار تشمل 16% ضريبة قيمة مضافة.",
    "terms_bullet1": "جميع أسعار القائمة بالشيلم الكيني وتشمل 16% ضريبة القيمة المضافة.",
    "terms_bullet2": "يتمتع أعضاء كولاي المسجلون بخصم 10% على الأطباق الموسمية الخاصة.",
