    "privacy_sec1_title": "1. Introduction et Engagement de Confidentialité Culinaire",
    "privacy_sec1_body": "Bienvenue au Kolay Restaurant. Nous respectons votre vie privée et nous nous engageons à protéger les données personnelles de nos clients.",
    "privacy_sec2_title": "2. Informations que Nous Collectons",
    "privacy_sec2_body": "Nous collectons les informations personnelles fournies volontairement lors des commandes :",
    "privacy_bullet1": "Coordonnées du client : Nom complet, numéro de téléphone, adresse e-mail et adresse de livraison.",
    "privacy_bullet2": "Préférences de commande : Articles du panier, remarques diététiques et instructions de livraison.",
    "privacy_bullet3": "Détails de réservation : Nombre de personnes, heure souhaitée et préférences de placement.",
    "privacy_bullet4": "Candidatures : CV, expérience professionnelle et demandes de renouvellement de contrat.",
    "privacy_bullet5": "Stockage des préférences : Langue sélectionnée et état du panier stockés localement.",
    "privacy_sec3_title": "3. Finalité et Utilisation des Données",
    "privacy_sec3_body": "Vos informations sont strictement utilisées pour offrir une expérience gastronomique exceptionnelle :",
    "privacy_use1": "Préparer, expédier et exécuter vos commandes de nourriture et de boissons avec précision.",
    "privacy_use2": "Sécuriser les réservations de table et informer le personnel des demandes spéciales.",
    "privacy_use3": "Envoyer des mises à jour sur l'état des commandes, des reçus numériques et des confirmations.",
    "privacy_use4": "Évaluer les candidatures et traiter les renouvellements de contrats d'employés.",
    "privacy_sec4_title": "4. Stockage Local du Navigateur & Cookies",
    "privacy_sec4_body": "Kolay Restaurant utilise le stockage local du navigateur pour garantir une réactivité instantanée.",
    "privacy_sec5_title": "5. Protection des Données et Non-Divulgation aux Tiers",
    "privacy_sec5_body": "Nous utilisons un cryptage de niveau entreprise. Nous ne vendons NI ne louons JAMAIS les données personnelles.",
    "privacy_effective": "En vigueur depuis septembre 2026",
    "modal_open_full": "Ouvrir la page complète",
    "modal_close": "Fermer la fenêtre",
    "terms_sec1_title": "1. Acceptation des Conditions",
    "terms_sec1_body": "En accédant ou en utilisant la plateforme numérique du Kolay Restaurant, vous acceptez d'être lié par ces conditions.",
    "terms_sec2_title": "2. Commandes en Ligne, Tarifs et Remises Membres",
    "terms_sec2_body": "Toutes les commandes sont soumises à la disponibilité des plats. Les prix incluent 16 % de TVA.",
    "terms_bullet1": "Tous les prix sont affichés en shillings kényans (KES) et incluent 16 % de TVA.",
    "terms_bullet2": "Les membres enregistrés bénéficient de 10 % de réduction sur les spécialités de saison.",
    "terms_bullet3": "Les modes de paiement incluent l'espèces à la livraison et les paiements M-Pesa ou par carte.",
    "terms_bullet4": "Aucune modification ne peut être garantie une fois la commande \"En préparation\".",
    "terms_sec3_title": "3. Réservations de Table et Délai de Grâce de 15 Min",
    "terms_sec3_body": "Les réservations de table sont maintenues pendant un délai maximum de 15 minutes.",
    "terms_sec4_title": "4. Accès au Portail et Confidentialité du Compte",
    "terms_sec4_body": "Les utilisateurs sont responsables de la sécurité de leurs identifiants. Les portails du personnel sont strictement réservés.",
    "terms_sec5_title": "5. Candidatures et Renouvellements de Contrat",
    "terms_sec5_body": "Les candidats certifient que toutes les informations fournies sont exactes et authentiques.",
    "terms_sec6_title": "6. Propriété Intellectuelle et Droit Applicable",
    "terms_sec6_body": "Tous les logos, menus, photos et logiciels sont la propriété intellectuelle exclusive du Kolay Restaurant.",
