    "privacy_sec1_title": "1. ভূমিকা এবং রান্নাবান্নার গোপনীয়তার প্রতিশ্রুতি",
    "privacy_sec1_body": "Kolay Restaurant-এ স্বাগতম। আমরা আপনার গোপনীয়তাকে শ্রদ্ধা করি এবং ব্যক্তিতথ্য সুরক্ষায় প্রতিশ্রুতিবদ্ধ।",
    "privacy_sec2_title": "2. যে তথ্য আমরা সংগ্রহ করি",
    "privacy_sec2_body": "অর্ডার এবং যোগাযোগের সময় স্বেচ্ছায় প্রদত্ত ব্যক্তিতথ্য সংগ্রহ করা হয়:",
    "privacy_bullet1": "যোগাযোগের তথ্য: নাম, ফোন নম্বর, ইমেইল এবং ডেলিভারি ঠিকানা।",
    "privacy_bullet2": "অর্ডারের বিবরণ: কার্টের খাবার, বিশেষ ডায়েট নোট এবং ডেলিভারি নির্দেশনা।",
    "privacy_bullet3": "টেবিল বুকিং বিবরণ: অতিথির সংখ্যা, সময় এবং বসার পছন্দ।",
    "privacy_bullet4": "চাকরির আবেদন: রেজুমে, কাজের অভিজ্ঞতা এবং চুক্তি নবায়ন আবেদন।",
    "privacy_bullet5": "পছন্দ সংরক্ষণ: ভাষা নির্বাচন এবং কার্টের তথ্য ব্রাউজারে স্থানীয়ভাবে সংরক্ষিত।",
    "privacy_sec3_title": "3. ডেটা ব্যবহারের উদ্দেশ্য",
    "privacy_sec3_body": "আপনার তথ্য কেবল মানসম্পন্ন সেবা প্রদানের জন্য ব্যবহৃত হয়:",
    "privacy_use1": "আপনার খাবারের অর্ডার নির্ভুলভাবে প্রস্তুত ও সরবরাহ করা।",
    "privacy_use2": "টেবিল বুকিং নিশ্চিত করা এবং কর্মচারীদের বিশেষ অনুরোধ জানানো।",
    "privacy_use3": "অর্ডারের আপডেট, ডিজিটাল রসিদ এবং বুকিং নিশ্চিতকরণ পাঠানো।",
    "privacy_use4": "চাকরির আবেদন মূল্যায়ন এবং চুক্তি নবায়ন প্রক্রিয়া পরিচালনা।",
