    "terms_sec1_title": "1. শর্তাবলী সম্মতি",
    "terms_sec1_body": "Kolay Restaurant-এর ডিজিটাল প্ল্যাটফর্ম ব্যবহার করে আপনি এই শর্তাবলীতে সম্মত হচ্ছেন।",
    "terms_sec2_title": "2. অনলাইন অর্ডার, মূল্য এবং মেম্বার ডিসকাউন্ট",
    "terms_sec2_body": "সমস্ত অর্ডার প্রাপ্যতা সাপেক্ষ। প্রদর্শিত মূল্যে ১৬% ভ্যাট অন্তর্ভুক্ত রয়েছে।",
    "terms_bullet1": "মেনুর সব মূল্য কেনিয়ান শিলিং (KES)-এ প্রদর্শিত এবং ১৬% ভ্যাট অন্তর্ভুক্ত।",
    "terms_bullet2": "নিবন্ধিত সদস্যরা সিজনাল বিশেষ খাবারে ১০% ছাড় উপভোগ করেন।",
    "terms_bullet3": "পেমেন্ট পদ্ধতির মধ্যে ক্যাশ অন ডেলিভারি, M-Pesa এবং ব্যাংক কার্ড অন্তর্ভুক্ত।",
    "terms_bullet4": "অর্ডার \"প্রস্তুত হচ্ছে\" স্ট্যাটাসে চলে গেলে পরিবর্তনে নিশ্চয়তা দেওয়া যায় না।",
    "terms_sec3_title": "3. টেবিল বুকিং এবং ১৫ মিনিটের সময়ের নিয়ম",
    "terms_sec3_body": "বুক করা টেবিল নির্ধারিত সময়ের পর সর্বোচ্চ ১৫ মিনিট রাখা হয়।",
    "terms_sec4_title": "4. পোর্টাল অ্যাক্সেস এবং অ্যাকাউন্টের সংবেদনশীলতা",
    "terms_sec4_body": "ব্যবহারকারীরা তাদের পাসওয়ার্ড সুরক্ষার জন্য দায়ী। কর্মী পোর্টাল কেবল অনুমোদিত ব্যক্তিদের জন্য।",
    "terms_sec5_title": "5. চাকরির আবেদন এবং চুক্তি নবায়ন",
    "terms_sec5_body": "আবেদনকারীরা নিশ্চিত করেন যে সমস্ত প্রদত্ত তথ্যাবলী সঠিক এবং সত্য।",
