    "privacy_sec1_title": "1. Introdução e Compromisso de Privacidade Culinária",
    "privacy_sec1_body": "Bem-vindo ao Kolay Restaurant. Respeitamos a sua privacidade e protegemos os seus dados pessoais.",
    "privacy_sec2_title": "2. Informações que Recolhemos",
    "privacy_sec2_body": "Recolhemos informações pessoais fornecidas voluntariamente durante os pedidos:",
    "privacy_bullet1": "Detalhes de Contacto: Nome completo, telefone, e-mail e morada de entrega.",
    "privacy_bullet2": "Preferências de Pedido: Itens do carrinho, notas dietéticas e instruções de entrega.",
    "privacy_bullet3": "Detalhes de Reserva: Número de pessoas, hora pretendida e preferências de lugar.",
    "privacy_bullet4": "Candidaturas de Emprego: Currículo, experiência profissional e renovação de contratos.",
    "privacy_bullet5": "Armazenamento de Preferências: Idioma selecionado e estado do carrinho guardados localmente.",
    "privacy_sec3_title": "3. Finalidade e Uso dos Dados",
    "privacy_sec3_body": "As suas informações são utilizadas estritamente para oferecer uma experiência gastronómica excecional:",
    "privacy_use1": "Preparar, expedir e satisfazer os seus pedidos de comida e bebida com precisão.",
    "privacy_use2": "Garantir reservas de mesa e notificar a equipa sobre pedidos especiais.",
    "privacy_use3": "Enviar atualizações do estado do pedido, recibos digitais e confirmações de reserva.",
    "privacy_use4": "Avaliar candidaturas de emprego e processar renovações de contratos de funcionários.",
    "privacy_sec4_title": "4. Armazenamento Local do Navegador e Cookies",
    "privacy_sec4_body": "O Kolay Restaurant utiliza o Armazenamento Local do navegador para garantir uma resposta imediata.",
    "privacy_sec5_title": "5. Salvaguardas de Dados e Não Divulgação a Terceiros",
    "privacy_sec5_body": "Utilizamos encriptação de nível empresarial. NUNCA vendemos dados pessoais a terceiros.",
    "privacy_effective": "Válido a partir de Setembro de 2026",
    "modal_open_full": "Abrir Página Completa",
    "modal_close": "Fechar",
    "terms_sec1_title": "1. Aceitação dos Termos",
    "terms_sec1_body": "Ao aceder ou utilizar a plataforma do Kolay Restaurant, concorda em ficar vinculado a estes Termos de Uso.",
    "terms_sec2_title": "2. Pedidos Online, Preços e Descontos de Membros",
    "terms_sec2_body": "Todos os pedidos estão sujeitos a disponibilidade. Todos os preços incluem 16% de IVA.",
    "terms_bullet1": "Todos os preços do menu são apresentados em Xelins Quenianos (KES) e incluem 16% de IVA.",
    "terms_bullet2": "Os membros registados beneficiam de 10% de desconto nas especialidades da estação.",
    "terms_bullet3": "Os métodos de pagamento incluem dinheiro na entrega, M-Pesa e cartões de crédito.",
    "terms_bullet4": "Alterações não são garantidas após o pedido entrar no estado \"Em preparação\".",
    "terms_sec3_title": "3. Reservas de Mesa e Tolerância de 15 Minutos",
    "terms_sec3_body": "As reservas de mesa são mantidas por um período de tolerância máximo de 15 minutos.",
    "terms_sec4_title": "4. Acesso ao Portal e Confidencialidade da Conta",
    "terms_sec4_body": "Os utilizadores são responsáveis por proteger as suas credenciais. O portal da equipa é restrito.",
    "terms_sec5_title": "5. Candidaturas de Emprego e Renovação de Contratos",
    "terms_sec5_body": "Os candidatos certificam que todas as informações prestadas são verdadeiras.",
    "terms_sec6_title": "6. Propriedade Intelectual e Lei Aplicável",
    "terms_sec6_body": "Todas as marcas, logótipos, menus e software são propriedade intelectual do Kolay Restaurant.",
