    "privacy_sec1_title": "1. تعارف اور پرائیویسی کا عزم",
    "privacy_sec1_body": "Kolay Restaurant میں خوش آمدید۔ ہم آپ کی پرائیویسی کا احترام کرتے ہیں۔",
    "privacy_sec2_title": "2. وہ معلومات جو ہم جمع کرتے ہیں",
    "privacy_sec2_body": "ہم آرڈر اور بات چیت کے دوران خود فراہم کردہ معلومات جمع کرتے ہیں:",
    "privacy_bullet1": "رابطے کی تفصیلات: پورا نام، فون نمبر، ای میل اور پتہ۔",
    "privacy_bullet2": "آرڈر کی ترجیحات: کارٹ اشیاء، غذائی نوٹس اور ڈیلیوری کی ہدایات۔",
    "privacy_bullet3": "ٹیبل بکنگ کی تفصیلات: مہمانوں کی تعداد، وقت اور نشست کی ترجیح۔",
    "privacy_bullet4": "نوکری کی درخواستیں: سی وی، کام کا تجربہ اور معاہدے کی تجدید۔",
    "privacy_bullet5": "ترجیحات کا ذخیرہ: منتخب زبان اور کارٹ کی معلومات براؤزر میں محفوظ۔",
    "privacy_sec3_title": "3. ڈیٹا کے استعمال کا مقصد",
    "privacy_sec3_body": "آپ کی معلومات صرف بہترین خدمت کی فراہمی کے لیے استعمال کی جاتی ہیں:",
    "privacy_use1": "آپ کے کھانے کا آرڈر درست طریقے سے تیار اور فراہم کرنا۔",
    "privacy_use2": "ٹیبل بکنگ اور خصوصی درخواستوں سے عملے کو آگاہ کرنا۔",
    "privacy_use3": "آرڈر کی صورتحال، ڈیجیٹل رسیدیں اور تصدیقی پیغامات بھیجنا۔",
    "privacy_use4": "نوکری کی درخواستوں کا جائزہ اور معاہدے کی تجدید۔",
    "privacy_sec4_title": "4. براؤزر لوکل اسٹوریج اور کوکیز",
    "privacy_sec4_body": "فوری جواب کے لیے براؤزر لوکل اسٹوریج کا استعمال کیا جاتا ہے۔",
    "privacy_sec5_title": "5. ڈیٹا کی حفاظت اور تیسرے فریق کو عدم فراہمی",
    "privacy_sec5_body": "ہم ڈیٹا کی حفاظت کے لیے مضبوط انکرپشن کا استعمال کرتے ہیں۔",
    "privacy_effective": "ستمبر 2026 سے نافذ العمل",
    "modal_open_full": "مکمل صفحہ کھولیں",
    "modal_close": "بند کریں",
    "terms_sec1_title": "1. شرائط کی قبولیت",
    "terms_sec1_body": "Kolay Restaurant کے پلیٹ فارم کا استعمال کرتے ہوئے آپ ان شرائط کو قبول کرتے ہیں۔",
    "terms_sec2_title": "2. آن لائن آرڈر، قیمتیں اور ممبر ڈسکاؤنٹ",
    "terms_sec2_body": "تمام آرڈرز کی فراہمی باورچی کی تصدیق کے مشروط ہے۔ تمام قیمتوں میں 16% ٹیکس شامل ہے۔",
    "terms_bullet1": "تمام قیمتیں کے ای ایس میں دکھائی گئی ہیں اور ان میں 16% ٹیکس شامل ہے۔",
    "terms_bullet2": "رجسٹرڈ ممبران کے لیے خصوصی ڈشز پر 10% رعایت۔",
    "terms_bullet3": "ادائیگی کی صورتوں میں نقد، M-Pesa اور کارڈ شامل ہیں۔",
    "terms_bullet4": "آرڈر کی تیاری شروع ہونے کے بعد تبدیلی کی ضمانت نہیں دی جا سکتی۔",
    "terms_sec3_title": "3. ٹیبل بکنگ اور 15 منٹ کی رعایتی مدت",
    "terms_sec3_body": "بک کی گئی میز مقررہ وقت کے بعد صرف 15 منٹ تک محفوظ رکھی جاتی ہے۔",
    "terms_sec4_title": "4. پورٹل تک رسائی اور اکاؤنٹ کی راز داری",
    "terms_sec4_body": "صارفین اپنے لاگ ان کی حفاظت کے ذمہ دار ہیں۔ عملے کا پورٹل صرف مجاز افراد کے لیے ہے۔",
    "terms_sec5_title": "5. نوکری کی درخواستیں اور معاہدے کی تجدید",
    "terms_sec5_body": "درخواست دہندگان تصدیق کرتے ہیں کہ فراہم کردہ تمام معلومات درست ہیں۔",
    "terms_sec6_title": "6. برانڈ کے حقوق اور قانون",
    "terms_sec6_body": "تمام برانڈنگ، لوگو، مینو اور سافٹ ویئر Kolay Restaurant کی ملکیت ہیں۔",
