    "privacy_sec1_title": "1. Einführung & Verpflichtung zum Datenschutz",
    "privacy_sec1_body": "Willkommen im Kolay Restaurant. Wir respektieren Ihre Privatsphäre und schützen Ihre persönlichen Daten.",
    "privacy_sec2_title": "2. Informationen, die wir sammeln",
    "privacy_sec2_body": "Wir erfassen personenbezogene Daten, die bei Bestellungen freiwillig angegeben werden:",
    "privacy_bullet1": "Kontaktdaten: Vollständiger Name, Telefonnummer, E-Mail-Adresse und Lieferadresse.",
    "privacy_bullet2": "Bestellpräferenzen: Warenkorb-Artikel, diätetische Hinweise und Lieferanweisungen.",
    "privacy_bullet3": "Reservierungsdetails: Personenanzahl, Wunschzeit und Sitzplatzpräferenzen.",
    "privacy_bullet4": "Bewerbungen: Lebenslauf, Berufserfahrung und Verlängerungsanträge.",
    "privacy_bullet5": "Präferenzspeicherung: Gewählte Sprache und Warenkorb-Status lokal gespeichert.",
    "privacy_sec3_title": "3. Zweck & Verwendung der Daten",
    "privacy_sec3_body": "Ihre Daten werden ausschließlich für ein außergewöhnliches Gastronomie-Erlebnis verwendet:",
    "privacy_use1": "Präzise Zubereitung, Auslieferung und Erfüllung Ihrer Speise- und Getränkebestellungen.",
    "privacy_use2": "Sicherung von Tischreservierungen und Benachrichtigung des Personals über Sonderwünsche.",
    "privacy_use3": "Versand von Bestellstatus-Updates, digitalen Quittungen und Reservierungsbestätigungen.",
    "privacy_use4": "Auswertung von Bewerbungen und Bearbeitung von Vertragsverlängerungen.",
    "privacy_sec4_title": "4. Browser Local Storage & Cookies",
    "privacy_sec4_body": "Kolay Restaurant nutzt Local Storage für eine sofortige Reaktionszeit.",
    "privacy_sec5_title": "5. Datensicherheit & Keine Weitergabe an Dritte",
    "privacy_sec5_body": "Wir verwenden hochgradige Verschlüsselung. Wir verkaufen Ihre Daten NIEMALS an Dritte.",
    "privacy_effective": "Gültig ab September 2026",
    "modal_open_full": "Vollständige Seite öffnen",
    "modal_close": "Fenster schließen",
    "terms_sec1_title": "1. Zustimmung zu den Bedingungen",
    "terms_sec1_body": "Durch die Nutzung der Plattform von Kolay Restaurant erklären Sie sich mit diesen Bedingungen einverstanden.",
    "terms_sec2_title": "2. Online-Bestellungen, Preise & Mitgliederrabatte",
    "terms_sec2_body": "Alle Bestellungen gelten vorbehaltlich Verfügbarkeit. Alle Preise enthalten 16 % MwSt.",
    "terms_bullet1": "Alle Speisekartenpreise sind in Kenia-Schilling (KES) angegeben und enthalten 16 % MwSt.",
    "terms_bullet2": "Registrierte Mitglieder erhalten 10 % Rabatt auf saisonale Spezialitäten.",
    "terms_bullet3": "Zahlungsmethoden umfassen Barzahlung bei Lieferung sowie M-Pesa und Kartenzahlung.",
    "terms_bullet4": "Änderungen können nicht garantiert werden, sobald die Bestellung \"In Zubereitung\" ist.",
    "terms_sec3_title": "3. Tischreservierung & 15-Minuten-Toleranzzeit",
    "terms_sec3_body": "Reservierte Tische werden bis zu 15 Minuten nach der gebuchten Zeit freigehalten.",
    "terms_sec4_title": "4. Portal-Zugriff & Vertraulichkeit des Kontos",
    "terms_sec4_body": "Benutzer sind für den Schutz ihrer Zugangsdaten verantwortlich. Das Personal-Portal ist autorisiertem Personal vorbehalten.",
    "terms_sec5_title": "5. Bewerbungen & Vertragsverlängerungen",
    "terms_sec5_body": "Bewerber bestätigen die Richtigkeit aller eingereichten Unterlagen und Angaben.",
    "terms_sec6_title": "6. Geistiges Eigentum & Anwendbares Recht",
    "terms_sec6_body": "Alle Logos, Speisekarten, Fotos und Software sind geistiges Eigentum von Kolay Restaurant.",
