    "Items": "Articoli",
    "privacy_sec1_title": "1. Introduzione e Impegno per la Privacy Culinaria",
    "privacy_sec1_body": "Benvenuti al Ristorante Kolay. Rispettiamo la vostra privacy e ci impegniamo a proteggere i vostri dati personali.",
    "privacy_sec2_title": "2. Informazioni che Raccogliamo",
    "privacy_sec2_body": "Raccogliamo informazioni personali fornite volontariamente durante gli ordini:",
    "privacy_bullet1": "Dettagli di Contatto: Nome completo, telefono, e-mail e indirizzo di consegna.",
    "privacy_bullet2": "Preferenze Ordine: Articoli nel carrello, note dietetiche e istruzioni di consegna.",
    "privacy_bullet3": "Dettagli Prenotazione: Numero ospiti, orario richiesto e preferenze di posto.",
    "privacy_bullet4": "Candidature di Lavoro: Curriculum, esperienze e rinnovo contratti staff.",
    "privacy_bullet5": "Memorizzazione Preferenze: Lingua selezionata e stato carrello salvati localmente.",
    "privacy_sec3_title": "3. Scopo e Utilizzo dei Dati",
    "privacy_sec3_body": "I vostri dati vengono utilizzati unicamente per offrire un'esperienza gastronomica d'eccellenza:",
    "privacy_use1": "Preparare, spedire e completare con precisione i vostri ordini di cibo e bevande.",
    "privacy_use2": "Confermare le prenotazioni e informare lo staff di eventuali richieste speciali.",
    "privacy_use3": "Inviare aggiornamenti sull'ordine, ricevute digitali e conferme di prenotazione.",
    "privacy_use4": "Valutare le candidature e gestire i rinnovi contrattuali del personale.",
    "privacy_sec4_title": "4. Local Storage del Browser e Cookie",
    "privacy_sec4_body": "Il Ristorante Kolay utilizza il Local Storage per garantire una risposta immediata.",
    "privacy_sec5_title": "5. Protezione dei Dati e Non Divulgazione a Terzi",
    "privacy_sec5_body": "Utilizziamo la crittografia aziendale. Non vendiamo MAI i dati personali a terzi.",
    "privacy_effective": "In vigore da Settembre 2026",
    "modal_open_full": "Apri Pagina Completa",
    "modal_close": "Chiudi Finestra",
    "terms_sec1_title": "1. Accettazione dei Termini",
    "terms_sec1_body": "Accedendo o utilizzando la piattaforma del Ristorante Kolay, accetti di essere vincolato da questi Termini di Utilizzo.",
    "terms_sec2_title": "2. Ordini Online, Prezzi e Sconti Membri",
    "terms_sec2_body": "Tutti gli ordini sono soggetti a disponibilità. Tutti i prezzi includono il 16% di IVA.",
    "terms_bullet1": "Tutti i prezzi del menu sono espressi in Scellini Kenioti (KES) e includono il 16% di IVA.",
    "terms_bullet2": "I membri registrati usufruiscono del 10% di sconto sulle specialità di stagione.",
    "terms_bullet3": "I metodi di pagamento includono contanti alla consegna, M-Pesa e carte di credito.",
    "terms_bullet4": "Le modifiche non sono garantite una volta che l'ordine passa a \"In Preparazione\".",
    "terms_sec3_title": "3. Prenotazione Tavoli e Tolleranza di 15 Minuti",
    "terms_sec3_body": "I tavoli prenotati vengono tenuti per un massimo di 15 minuti oltre l'orario concordato.",
    "terms_sec4_title": "4. Accesso al Portale e Riservatezza Account",
    "terms_sec4_body": "Gli utenti sono responsabili della custodia delle proprie credenziali. I portali staff sono strettamente riservati.",
    "terms_sec5_title": "5. Candidature e Rinnovo Contratti Staff",
    "terms_sec5_body": "I candidati certificano che tutte le informazioni e i documenti inviati sono accurati.",
    "terms_sec6_title": "6. Proprietà Intellettuale e Legge Applicabile",
    "terms_sec6_body": "Tutti i marchi, logo, menu e software sono proprietà intellettuale esclusiva del Ristorante Kolay.",
