    "privacy_sec1_title": "1. はじめに＆プライバシーへの取り組み",
    "privacy_sec1_body": "Kolay Restaurantへようこそ。お客様のプライバシーを尊重し、個人情報の保護に努めております。",
    "privacy_sec2_title": "2. 収集する情報",
    "privacy_sec2_body": "ご注文や各種ご利用時にご提供いただく個人情報を収集いたします：",
    "privacy_bullet1": "お客様連絡先：氏名、電話番号、メールアドレス、お届け先住所。",
    "privacy_bullet2": "ご注文・お食事の好みの詳細：カート内容、アレルギー・食事制限メモ、配送・持ち帰り指示。",
    "privacy_bullet3": "テーブル予約詳細：ご来店人数、ご希望時間、お祝い等の目的、お席の希望。",
    "privacy_bullet4": "求応募情報：履歴書、職務経歴書、スタッフ契約更新申請。",
    "privacy_bullet5": "設定の保存：選択した言語およびカートの状態をブラウザにローカル保存。",
    "privacy_sec3_title": "3. データの利用目的",
    "privacy_sec3_body": "お客様の情報は、最高の美食体験を提供するためにのみ使用されます：",
    "privacy_use1": "お食事・お飲み物のご注文を正確に調理・配送・提供すること。",
    "privacy_use2": "テーブル予約を確保し、特別なご要望を店舗スタッフに共有すること。",
    "privacy_use3": "注文状況の更新、デジタル領収書、予約確定通知の送信。",
    "privacy_use4": "採用応募の審査および従業員の契約更新手続き。",
    "privacy_sec4_title": "4. ローカルストレージとクッキー",
    "privacy_sec4_body": "快適な操作感を提供するため、言語設定やカート情報をブラウザのローカルストレージに保存します。",
    "privacy_sec5_title": "5. 数据の安全管理と第三者非开示",
    "privacy_sec5_body": "高度な暗号化技術により情報を保護しています。お客様のデータを第三者に販売・提供することは絶対にありません。",
    "privacy_effective": "発効日：2026年9月",
    "modal_open_full": "全画面ページを開く",
    "modal_close": "閉じる",
    "terms_sec1_title": "1. 利用規約への同意",
    "terms_sec1_body": "Kolay Restaurantのデジタルサービス・オンライン注文・予約システムをご利用いただくことで、本規約に同意されたものとみなします。",
    "terms_sec2_title": "2. オンライン注文・価格表記・会員割引",
    "terms_sec2_body": "ご注文は仕入れ状況等により変更となる場合がございます。表示価格には16%の消費税が含まれます。",
    "terms_bullet1": "すべてのメニュー価格はケニア・シリング（KES）表示で、16%の付加価値税（VAT）を含みます。",
    "terms_bullet2": "Kolay無料会員様は、季節のシェフおすすめ料理を10%引きでお楽しみいただけます。",
    "terms_bullet3": "お支払い方法は、代金引換（現金）、M-Pesa、各種クレジットカードをご利用いただけます。",
    "terms_bullet4": "厨房で調理が開始（\"Preparing\"状態）された後のご注文内容の変更は承れない場合がございます。",
    "terms_sec3_title": "3. ご来店予約と15分間の保持保証",
    "terms_sec3_body": "ご予約テーブルは、ご予約時刻から15分間キープさせていただきます。それ以降はキャンセル扱いとなる場合がございます。",
