    "Items": "개",
    "privacy_sec1_title": "1. 소개 및 개인정보 보호 약속",
    "privacy_sec1_body": "Kolay Restaurant에 오신 것을 환영합니다. 고객님의 개인정보를 존중하고 안전하게 보호합니다.",
    "privacy_sec2_title": "2. 수집하는 정보",
    "privacy_sec2_body": "주문 및 서비스 이용 시 자발적으로 제공해주시는 개인정보를 수집합니다:",
    "privacy_bullet1": "고객 연락처: 성함, 전화번호, 이메일 주소, 배송지 주소.",
    "privacy_bullet2": "주문 선호도: 장바구니 품목, 식이 요청사항, 배달/포장 지시사항.",
    "privacy_bullet3": "테이블 예약 상세: 방문 인원, 요청 시간, 기념일 태그 및 좌석 선호도.",
    "privacy_bullet4": "채용 지원 정보: 이력서, 경력 사항, 자격 증명 및 계약 갱신 신청서.",
    "privacy_bullet5": "설정 저장: 선택한 언어 및 장바구니 상태를 브라우저에 로컬 저장.",
    "privacy_sec3_title": "3. 개인정보 이용 목적",
    "privacy_sec3_body": "고객님의 정보는 최고의 미식 경험을 제공하기 위해 엄격히 사용됩니다:",
    "privacy_use1": "주문하신 음식을 정확하게 조리, 배달 및 서빙하기 위함.",
    "privacy_use2": "테이블 예약을 확정하고 특별 요청사항을 직원에게 전달하기 위함.",
    "privacy_use3": "주문 진행 상황, 디지털 영수증 및 예약 확정 안내문 발송.",
    "privacy_use4": "채용 지원서 검토 및 직원 계약 갱신 심사.",
    "privacy_sec4_title": "4. 브라우저 로컬 스토리지 및 쿠키",
    "privacy_sec4_body": "빠른 웹 응답 속도를 위해 언어 설정 및 장바구니 데이터를 브라우저 로컬 스토리지에 캐싱합니다.",
    "privacy_sec5_title": "5. 데이터 보안 및 제3자 제공 금지",
    "privacy_sec5_body": "기업급 암호화 기술로 데이터를 철저히 보호하며, 어떠한 경우에도 제3자에게 개인정보를 판매하거나 공유하지 않습니다.",
    "privacy_effective": "시행일: 2026년 9월",
    "modal_open_full": "전체 페이지 보기",
    "modal_close": "닫기",
    "terms_sec1_title": "1. 약관 동의",
    "terms_sec1_body": "Kolay Restaurant의 온라인 주문 및 예약 플랫폼을 이용함으로써 본 이용약관에 동의하게 됩니다.",
    "terms_sec2_title": "2. 온라인 주문, 가격 정책 및 회원 할인",
    "terms_sec2_body": "모든 주문은 재고 및 조리 가능 여부에 따라 변경될 수 있습니다. 표시 가격에는 16% 부가세가 포함되어 있습니다.",
    "terms_bullet1": "모든 메뉴 가격은 케냐 실링(KES)으로 표시되며 16% 부가가치세가 포함됩니다.",
    "terms_bullet2": "Kolay 등록 회원은 계절 스페셜 메뉴 10% 할인 혜택을 받으실 수 있습니다.",
    "terms_bullet3": "결제 수단은 수령 시 현금 결제, M-Pesa 및 신용카드 결제를 지원합니다.",
    "terms_bullet4": "주방 시스템에서 \"조리 중\" 상태로 전환된 후에는 주문 변경이 어려울 수 있습니다.",
    "terms_sec3_title": "3. 테이블 예약 및 15분 대기 정책",
    "terms_sec3_body": "예약된 테이블은 예약 시간으로부터 최대 15분간 보장되며, 이후에는 순번 고객에게 배정될 수 있습니다.",
    "terms_sec4_title": "4. 포털 접근 권한 및 계정 보안",
    "terms_sec4_body": "계정 정보 관리 책임은 사용자 본인에게 있습니다. 직원 및 관리자 포털은 인가된 임직원만 접근할 수 있습니다.",
    "terms_sec5_title": "5. 채용 지원 및 직원 계약 갱신",
    "terms_sec5_body": "채용 지원서 및 계약 갱신 신청서 제출자는 기재된 모든 정보가 사실임을 증명해야 합니다.",
    "terms_sec6_title": "6. 지적 재산권 및 준거법",
    "terms_sec6_body": "모든 브랜드 로고, 메뉴, 사진, UI 디자인 및 시스템 소스코드는 Kolay Restaurant의 지적 재산입니다.",
