    "privacy_sec1_body": "Kolay Restaurant'a hoş geldiniz. Gizliliğinize saygı duyuyor ve kişisel verilerinizi koruyoruz.",
    "privacy_sec2_title": "2. Topladığımız Bilgiler",
    "privacy_sec2_body": "Sipariş ve etkileşim sırasında gönüllü olarak sağlanan kişisel bilgileri topluyoruz:",
    "privacy_bullet1": "İletişim Bilgileri: Ad soyad, telefon numarası, e-posta ve teslimat adresi.",
